-- 1. Add generated search vector column
ALTER TABLE articles 
ADD COLUMN search_vector tsvector 
GENERATED ALWAYS AS (to_tsvector('english', coalesce(title, '') || ' ' || coalesce(body, ''))) STORED;

-- 2. Create GIN index
CREATE INDEX idx_articles_search_gin ON articles USING gin (search_vector);

-- 3. Millisecond search query
SELECT id, title 
FROM articles 
WHERE search_vector @@ to_tsquery('english', 'postgresql & performance');

-- Containment queries on a JSONB column
CREATE INDEX idx_events_payload
ON events USING gin (payload jsonb_path_ops);

SELECT id
FROM events
WHERE payload @> '{"type":"purchase"}';

-- Trigram index for substring search
CREATE EXTENSION IF NOT EXISTS pg_trgm;

CREATE INDEX idx_products_name_trgm
ON products USING gin (name gin_trgm_ops);

SELECT id, name
FROM products
WHERE name ILIKE '%keyboard%';
